        dynamic([_, _, _, _, _, _, _, _, _, q], sum(field(q, ^key)) >= ^value)

      {:not, {:sum, {:<, value}}} ->
        dynamic([_, _, _, _, _, _, _, _, _, q], not (sum(field(q, ^key)) < ^value))

      {:sum, {:<, value}} ->
        dynamic([_, _, _, _, _, _, _, _, _, q], sum(field(q, ^key)) < ^value)

      {:not, {:sum, {:<=, value}}} ->
        dynamic([_, _, _, _, _, _, _, _, _, q], not (sum(field(q, ^key)) <= ^value))

      {:sum, {:<=, value}} ->
        dynamic([_, _, _, _, _, _, _, _, _, q], sum(field(q, ^key)) <= ^value)

      {:not, {:sum, {:==, nil}}} ->
        dynamic([_, _, _, _, _, _, _, _, _, q], sum(field(q, ^key)) != ^nil)

      {:sum, {:==, nil}} ->
        dynamic([_, _, _, _, _, _, _, _, _, q], sum(field(q, ^key)) == ^nil)

      {:not, {:sum, {:==, value}}} ->
        dynamic([_, _, _, _, _, _, _, _, _, q], sum(field(q, ^key)) != ^value)

      {:sum, {:==, value}} ->
        dynamic([_, _, _, _, _, _, _, _, _, q], sum(field(q, ^key)) == ^value)

      {:not, {:sum, {:!=, nil}}} ->
        dynamic([_, _, _, _, _, _, _, _, _, q], sum(field(q, ^key)) == ^nil)

      {:sum, {:!=, nil}} ->
        dynamic([_, _, _, _, _, _, _, _, _, q], sum(field(q, ^key)) != ^nil)

      {:not, {:sum, {:!=, value}}} ->
        dynamic([_, _, _, _, _, _, _, _, _, q], sum(field(q, ^key)) == ^value)

      {:sum, {:!=, value}} ->
        dynamic([_, _, _, _, _, _, _, _, _, q], sum(field(q, ^key)) != ^value)
    end
  end

  def dynamic_expr(_, _, _, _) do
    nil
  end
end